def transform(grid):
 from collections import Counter
 h,w=len(grid),len(grid[0])
 pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c] in (8,2)]
 a=min(r for r,c in pts); b=max(r for r,c in pts); l=min(c for r,c in pts); u=max(c for r,c in pts)
 rings={}
 for r in range(h):
  for c in range(w):
   if grid[r][c] not in (8,2):
    d=min(r,c,h-1-r,w-1-c)
    rings.setdefault(d,Counter())[grid[r][c]]+=1
 colors={d:v.most_common(1)[0][0] for d,v in rings.items()}
 out=[[colors.get(min(r,c,h-1-r,w-1-c),0) for c in range(l,u+1)] for r in range(a,b+1)]
 marker=next((r,c) for r,c in pts if grid[r][c]==2)
 if marker==(a,u):
  out=[list(row) for row in zip(*out)][::-1]
 elif marker==(b,u):
  out=[row[::-1] for row in out[::-1]]
 elif marker==(b,l):
  out=[list(row) for row in zip(*out[::-1])]
 return out

